import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[3];K=Path(__file__).resolve().parent;B=K/'batches/edition-34';S=R/'projects/site';now=datetime.now(timezone.utc).isoformat()
q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True)
rows=[(595, 'balcony-with-drying-sari', 'A small balcony', 'The poem makes the apartment balcony a centre of ordinary life inside a carefully earned but socially enclosed home. Attend to the drying sari and bounded space, without an aspirational real-estate display or an inventory of every noun.', 'Horizontal 3:2 graphite and dilute watercolor architectural crop, eye level from within a modest urban Indian apartment balcony. A plain muted indigo cotton sari with a narrow faded rust border hangs doubled over one taut clothesline fixed between two walls, lower folds gently weighted by dampness and a small breeze lifting only the right corner. It fills the left third, with unequal natural folds and plausible cloth gravity. Simple unornamented metal railing recedes across the lower middle; a softly defined neighbouring apartment wall is glimpsed beyond. One small terracotta pot at the extreme lower edge holds an ordinary plant with two half-open pale flowers, mostly cropped. Reserve the right third as warm pale plaster and quiet reflected daylight. Restrained graphite construction lines and soft blue washes, selective detail where cloth contacts line. No cup, furniture arrangement, people, luxury vista, picturesque ruin, decorative text or additional props. The visual feeling is sheltered everyday life with a trace of enclosure.'), (602, 'friends-found-again', 'Friends found again', 'After lost youth and unhelpful cliches, a reunion returns the speaker to shared delight. Small anonymous figures give the warmth of meeting without inventing a portrait of the poet or documenting his real academy friends.', 'Horizontal 3:2 matte gouache literary painting, a wide quiet shaded island courtyard near a muted grey-blue sea. Three small fictional older Indian adults in plain everyday short-sleeved shirts and trousers occupy the left-middle, no one identifiable and faces only understated paint marks. Two old friends lean into a relaxed greeting with one hand naturally on the other shoulder; a third stands beside them, torso gently bent with laughter. Three coherent bodies, six legs, grounded feet, arms naturally attached and occluded where they overlap; no exaggerated gestures. Grey hair suggested sparingly. Figures occupy less than a quarter of the composition. Broad unoccupied warm stone ground stretches to the right and lower edge, a low distant horizon through open space, no palm-tree or resort-postcard staging. Diffuse afternoon shade, two ochre/blue clothing accents, broad matte planes and only selective edge definition. No wheelchair as a prop, age stereotypes, visible writing, uniforms, medals, banners, champagne, tourist architecture or photorealism.'), (607, 'water-carrying-on', 'Water carrying on', 'Water accepts dirt while continuing forward without reward. A close material observation of flowing water carrying a fine sediment plume preserves the poem’s movement without a generic mountain panorama or moral-symbol collage.', 'Horizontal 3:2 near-abstract ink and transparent watercolor observation looking closely down at shallow moving water. One broad flat grey stone enters from the left edge, partly submerged; a thin ochre sediment veil gently lifts from its lower edge into the current and trails diagonally towards the lower right. Water depth and stone refraction are quiet and plausible. A few restrained broken pale reflections curve around the stone, leaving the upper right as an open almost colorless plane. Not a river landscape, stream through scenery, waterfall, galaxy, decorative marbling or polished spa-stone arrangement. Muted mineral grey, dilute blue-green and one ochre wash; soft wet paint transitions and selective dark ink only under the stone’s waterline. No mechanical texture, glitter, leaves, flowers, text, people or religious symbols. Natural movement and unobtrusive service; opaque pale paper background with dissolved paint edges.')]
items=[]
for pid,ident,title,reason,scene in rows:
 p=S/f'content/editions/issue-34/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/f'poem-{pid}.json';snapshot.write_bytes(p.read_bytes())
 prompt=f'Use case: illustration-story. Original horizontal 3:2 literary artwork for Kabita Live Issue34. Human Natural in Poetic Natural mode. Preserve the selected expressive medium; a painted interpretation, never documentary evidence.\nEmotional anchor: {reason}\nScene and medium: {scene}\nAnti-optimization checks: avoid staged object display, equal detail everywhere, mechanically repeated shapes, theatrical lighting and cosmetic distress. Material contact, geometry and illumination must make sense. Preserve quiet negative space and emotional ambiguity. No identifiable real people, portraits, readable text, signature, logos or watermark. Fictional anonymous small adults are allowed only in the reunion scene above; no real-person likeness or documentary claim. Opaque ivory-paper background.\nPoem {d["title"]} by {d["author"]}; source read fully, use as context only, never render the words:\n{d["text"]}\n'
 pp=B/f'{ident}-prompt.txt';pp.write_text(prompt)
 items.append(dict(id=ident,edition=34,poem_id=pid,title=title,rationale=reason,status='pending',prompt=str(pp.relative_to(R)),poem_source=str(p.relative_to(R)),poem_evidence=str(snapshot.relative_to(R)),poem_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),output=f'kb/artifacts/artwork/edition-art-rollout-2026-10-04/edition-34/{ident}/v1.png',attempts=[],independent=False))
plain=[{'poem_id': 592, 'rationale': 'Let the author’s witness to the Pahalgam attack stand in words; do not invent victims, identities or a documentary scene.', 'status': 'pending'}, {'poem_id': 598, 'rationale': 'The final arrival of spring is the poem’s revelation. A text-led opening lets the hospitality and transformation unfold without showing the ending in advance.', 'status': 'pending'}, {'poem_id': 603, 'rationale': 'Preserve the urgent argument for an environment where a girl can grow safely, without a sentimental child illustration or surveillance imagery.', 'status': 'pending'}]
for p in (S/'content/editions/issue-34').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
